'use strict';
const C=Jimu, KEY='jimu-workbench-v1';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',bulb:'M9 18h6 M9 22h6 M8 14a7 7 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2',pen:'m16 3 5 5-12 12-6 1 1-6z M13 6l5 5',brief:'M3 7h18v14H3z M8 7V3h8v4 M3 12l9 3 9-3',video:'M3 5h13v14H3z M16 10l5-3v10l-5-3',chart:'M3 3v18h18 M7 16v-5 M12 16V6 M17 16v-8',calendar:'M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18 M7 14h3 M14 14h3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',check:'m5 12 4 4 10-10',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',play:'m8 5 11 7-11 7z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',flame:'M12 2c2 6 8 7 8 13a8 8 0 1 1-16 0c0-4 3-6 5-8 0 4 2 4 3 3z',bookmark:'M6 3h12v18l-6-4-6 4z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',close:'M5 5l14 14 M5 19 19 5',menu:'M3 6h18 M3 12h18 M3 18h18',link:'m10 13 4-4 M7 14l-2 2a4 4 0 0 0 6 6l3-3 M10 7l3-3a4 4 0 0 1 6 6l-2 2',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',file:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h8'};
const icon=(n,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.grid}"/></svg>`;
let S, storageError=false;try{const raw=localStorage.getItem(KEY);S=raw?C.validateImport(JSON.parse(raw)):C.seed();if(!raw)localStorage.setItem(KEY,JSON.stringify(S));}catch(e){S=C.seed();storageError=true;}
let filterCreator='all', dashTab='active', creatorTab='active', radar={platform:'全部',days:'7',track:'全部',keyword:'',saved:false}, modalReturn=null;
const navItems=[['home','grid','工作总览'],['creators','users','达人管理'],['planning','bulb','选题策划'],['scripts','pen','文案工作室'],['business','brief','商务合作'],['production','video','制作中心'],['analysis','search','视频分析'],['reviews','chart','数据复盘'],['weekly','calendar','周会中心']];
const pageNames=Object.fromEntries([...navItems,['radar','flame','热点雷达'],['business-radar','flame','商业热点雷达'],['library','bookmark','灵感收藏'],['settings','settings','系统设置'],['project','video','视频项目']].map(x=>[x[0],x[2]]));
const stageClass=s=>s===0?'amber':s===4?'purple':s===6?'red':s===7?'gray':'blue';
const creator=id=>S.creators.find(c=>c.id===id);
const activeCreators=()=>S.creators.filter(c=>c.status==='负责中');
const scoped=()=>S.projects.filter(p=>(filterCreator==='all'?creator(p.creatorId)?.status==='负责中':p.creatorId===filterCreator));
const fmt=n=>new Intl.NumberFormat('zh-CN').format(n||0);
const compact=n=>n>=10000?(n/10000).toFixed(1)+'万':fmt(n);
const date=(s,full=false)=>s?new Date(s).toLocaleString('zh-CN',full?{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}:{month:'numeric',day:'numeric'}):'未设置';
const localInput=s=>{const d=s?new Date(s):new Date();return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const safeUrl=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}};
function toast(msg,error=false){$('#toast').textContent=msg;$('#toast').className='show'+(error?' error':'');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').className='',4000);}
function persist(msg){try{localStorage.setItem(KEY,JSON.stringify(S));storageError=false;if(msg)toast(msg);return true;}catch(e){storageError=true;toast('保存失败：浏览器存储不可用或已满。请先导出备份，当前更改仅保留在本页。',true);return false;}}
function go(page){location.hash=page;}
function getRoute(){const parts=(location.hash.slice(1)||'home').split('/');return [parts[0],parts[1]];}
const btn=(label,action,id='',cls='',ico='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${ico?icon(ico,15):''}${label}</button>`;
const linkBtn=(label,path,cls='',ico='')=>`<a class="btn ${cls}" href="#${path}">${ico?icon(ico,15):''}${label}</a>`;
const pill=(t,cl='')=>`<span class="pill ${cl}">${esc(t)}</span>`;
const avatar=(c,large=false)=>`<span class="avatar ${['peach','sage','lilac','blue'].includes(c?.color)?c.color:'sage'} ${large?'large':''}">${esc(c?.name?.slice(0,1))}</span>`;
function heading(en,title,sub,actions=''){return `<div class="heading"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
const notice=(text,cl='')=>`<div class="notice ${cl}">${text}</div>`;
const empty=(t,sub,action='')=>`<div class="empty"><h3>${t}</h3><p>${sub}</p><div style="margin-top:20px">${action}</div></div>`;
const creatorOptions=(selected,activeOnly=false)=>S.creators.filter(c=>!activeOnly||c.status==='负责中').map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}${c.status!=='负责中'?' · '+esc(c.status):''}</option>`).join('');
function shell(body,page){return `<div class="mobile-shade" data-action="menu"></div><aside class="sidebar"><a class="brand" href="#home"><span class="logo"><i></i><i></i><i></i><i></i></span><div><b>积木工作台</b><small>JIMU CREATOR STUDIO</small></div></a><div class="workspace-label">我的创作空间</div><nav class="nav">${navItems.map(([key,ic,t])=>`<a href="#${key}" class="${page===key||(key==='planning'&&['radar','library'].includes(page))||(key==='business'&&page==='business-radar')?'active':''}">${icon(ic)}${t}${key==='production'?`<span class="count">${scoped().filter(p=>p.stage>=3&&p.stage<=4).length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-card"><b>${icon('spark',14)} 给创作，留一点空间</b>让重复的事变简单<br>把精力留给好内容</div><nav class="nav"><a href="#settings" class="${page==='settings'?'active':''}">${icon('settings')}系统设置</a></nav><div class="user"><span class="avatar me">木</span><div><b>积木的工作空间</b><small>内容编导 · 本地体验版</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="menu-toggle" data-action="menu" aria-label="打开导航">${icon('menu')}</button><span>工作空间</span><span>/</span><b>${pageNames[page]||'工作总览'}</b></div><div class="top-actions"><select class="global-select" id="creator-filter" aria-label="筛选达人"><option value="all">全部负责中的达人</option>${creatorOptions(filterCreator)}</select><span class="save-dot">${storageError?'保存异常':'数据保存在当前浏览器'}</span><span class="avatar me">木</span></div></header><div class="content">${storageError?notice('浏览器存储异常，未覆盖原有数据。请先在设置中导出当前数据；确认备份后再处理存储。','amber'):''}${body}<footer class="footnote"><span>积木工作台 · 每一条好内容，都从一块小积木开始</span><span>交互原型 / 热点为示例或手动录入 / AI 为规则模拟</span></footer></div></main>`;}
function stat(label,value,sub,ic){return `<div class="stat"><div class="stat-label">${label}${icon(ic,15)}</div><div class="stat-value">${value}</div><small>${sub}</small><span class="stat-decoration" aria-hidden="true">${icon(ic,32)}</span></div>`;}
function videoRow(p){const c=creator(p.creatorId);return `<a class="video-row" href="#project/${esc(p.id)}"><div class="thumb ${c.color}">${icon(p.stage>=6?'chart':'video',23)}</div><div class="row-main"><div class="row-title">${esc(p.title)}</div><div class="row-meta"><span>${esc(c.name)}</span><span>·</span><span>${esc(c.track)}</span><span>· ${p.metrics?compact(p.metrics.plays)+' 播放':'计划 '+date(p.due)}</span></div></div><div class="row-stage">${pill(C.STAGES[p.stage],stageClass(p.stage))}<div class="dots">${C.STAGES.map((x,i)=>`<i class="${i<=p.stage?'done':''}"></i>`).join('')}</div></div></a>`;}
function home(){const ps=scoped(),doing=ps.filter(p=>p.stage<6),reviewing=ps.filter(p=>p.stage===6),published=ps.filter(p=>p.stage>=6&&new Date(p.publishedAt)>Date.now()-7*86400000);const rows=dashTab==='active'?doing:dashTab==='review'?reviewing:ps.filter(p=>p.stage===7);return heading('YOUR CREATIVE DAY','让好内容，从这里发生。','每一个小想法，都值得被认真完成。',btn('新建视频','new-project','','primary','plus'))+`<section class="hero"><div><div class="eyebrow">ONE IDEA. A WHOLE STORY.</div><h2>把好想法，拍成好内容。</h2><p>从灵感到发布，再从复盘找到下一次的方向。<br>今天，一起把创作往前推进一小步。</p>${btn('体验完整制作流程','demo','','primary','play')}</div><div class="hero-visual"><div class="block b1">${icon('play')}</div><div class="block b2">${icon('bulb')}</div><div class="block b3">${icon('spark')}</div><div class="block b4"></div></div></section><div class="stats">${stat('负责中的达人',filterCreator==='all'?activeCreators().length:1,'每个人，都有自己的故事','users')}${stat('正在制作',doing.length,'选题、脚本与制作持续推进','video')}${stat('近 7 天已发布',published.length,'以项目登记的发布时间为准','check')}${stat('等待复盘确认',reviewing.length,'最终方向，由编导决定','chart')}</div><div class="dashboard-grid"><section class="panel"><div class="section-head"><h2>内容正在发生 <small> / 视频项目</small></h2><a class="text-btn" href="#production">查看全部 ${icon('arrow',13)}</a></div><div class="tabs"><button data-action="dash-tab" data-id="active" class="${dashTab==='active'?'active':''}">进行中 <span>${doing.length}</span></button><button data-action="dash-tab" data-id="review" class="${dashTab==='review'?'active':''}">待复盘 ${reviewing.length}</button><button data-action="dash-tab" data-id="done" class="${dashTab==='done'?'active':''}">已确认方向</button></div>${rows.length?rows.slice(0,5).map(videoRow).join(''):empty('这一栏暂时留白','添加一个新想法，让内容开始发生。')}</section><aside class="dashboard-side"><section class="panel"><div class="section-head"><h2>${icon('clock',16)} 下一步，等你推进</h2><small>${doing.length+reviewing.length} 项</small></div>${[...doing.filter(p=>p.stage>=2),...reviewing, ...doing.filter(p=>p.stage<2)].slice(0,3).map(p=>`<a class="task" href="#project/${p.id}"><span class="task-icon">${icon(p.stage===4?'video':p.stage===6?'chart':'check',14)}</span><div><b>${esc(creator(p.creatorId).name)} · ${C.STAGES[p.stage]}</b><small>${esc(p.title)}</small></div></a>`).join('')||'<p class="copy">暂时没有待推进项目。</p>'}</section><section class="panel"><div class="section-head"><h2>${icon('flame',16)} 灵感补给站</h2>${pill('示例','amber')}</div>${S.hotspots.filter(h=>h.kind==='topic').slice(0,2).map((h,i)=>`<a class="hot-mini" href="#radar"><span class="rank">0${i+1}</span><div><b>${esc(h.title)}</b><p>${esc(h.platform)} · ${esc(h.track)}</p></div></a>`).join('')}<a href="#radar" class="text-btn" style="margin-top:18px">去热点雷达寻找灵感 ${icon('arrow',13)}</a></section></aside></div><div class="creator-strip">${activeCreators().slice(0,4).map(c=>`<button class="mini-creator" data-action="select-creator" data-id="${c.id}">${avatar(c)}<div><b>${esc(c.name)}</b><small>${esc(c.track)} · ${S.projects.filter(p=>p.creatorId===c.id&&p.stage<6).length} 个进行中</small></div></button>`).join('')}</div>`;}
function creatorsPage(){const cs=S.creators.filter(c=>creatorTab==='all'||(creatorTab==='active'?c.status==='负责中':c.status!=='负责中'));return heading('THE PEOPLE BEHIND THE STORIES','每个人，都有自己的故事。','管理达人档案，让每一次策划更贴近真实的人。',btn('新增达人','new-creator','','primary','plus'))+`<div class="subnav">${[['active','负责中'],['history','暂停 / 移交 / 归档'],['all','全部达人']].map(([id,t])=>`<button data-action="creator-tab" data-id="${id}" class="${creatorTab===id?'active':''}">${t}</button>`).join('')}</div><div class="grid2">${cs.map(c=>`<section class="panel creator-card"><div class="creator-top">${avatar(c,true)}<div><h3>${esc(c.name)}</h3>${pill(c.track)} ${pill(c.status,c.status==='负责中'?'':'gray')}</div></div><p>${esc(c.tag||c.profile)}</p><div class="creator-stats"><div><b>${S.projects.filter(p=>p.creatorId===c.id&&p.stage<6).length}</b>制作中</div><div><b>${S.projects.filter(p=>p.creatorId===c.id&&p.stage>=6).length}</b>已发布</div><div><b style="font-size:15px;line-height:26px">${esc(c.owner)}</b>当前负责人</div></div><p>人物特点：${esc(c.profile)}</p><p>内容边界：${esc(c.taboos||'待补充')}</p><div class="card-actions">${btn('编辑档案','edit-creator',c.id,'small','pen')}${btn('移交','transfer-creator',c.id,'small')}${btn(c.status==='已归档'?'恢复负责':'归档','archive-creator',c.id,'small')}${btn('查看项目','select-creator',c.id,'small soft','arrow')}</div>${c.history.length?`<details style="margin-top:16px"><summary class="copy">负责人 / 状态变更记录 (${c.history.length})</summary><div class="log-list">${c.history.map(h=>`${date(h.at,true)} · ${esc(h.text)}`).join('<br>')}</div></details>`:''}</section>`).join('')}</div>${!cs.length?empty('暂时没有达人','可以随时新增，也可以恢复已归档的达人。'):''}`;}
function planning(){return heading('FROM A SPARK TO A STORY','好选题，先从真实生活开始。','记录灵感、明确切入角度，再由编导确认进入制作。',btn('新建选题','new-project','','primary','plus'))+`<div class="subnav"><a class="active" href="#planning">选题库</a><a href="#radar">${icon('flame',14)} 热点雷达</a><a href="#library">${icon('bookmark',14)} 灵感收藏</a></div>${notice('模拟策划会参考达人档案与内容边界；生成内容始终是待编辑、待确认的草稿。')}<div class="grid3">${scoped().filter(p=>p.stage<=1).map(p=>`<section class="panel hot-card"><div class="card-top">${pill(creator(p.creatorId).name)}${pill(C.STAGES[p.stage],'amber')}</div><h3>${esc(p.title)}</h3><p>${esc(p.angle)}</p><div class="source">来源：${esc(p.source)}${p.parentId?' · 已关联上一条复盘':''}</div><div class="card-actions">${linkBtn('继续策划','project/'+p.id,'primary','arrow')}</div></section>`).join('')}</div>${!scoped().some(p=>p.stage<=1)?empty('把今天的灵感放在这里','从热点雷达收藏一个想法，或直接新建选题。'):''}`;}
function radarPage(kind='topic',savedOnly=false){if(savedOnly)radar.days='all';else if(radar.days==='all')radar.days='7';let hs=S.hotspots.filter(h=>(savedOnly?S.favorites.includes(h.id):h.kind===kind)&&(radar.platform==='全部'||h.platform===radar.platform)&&(radar.track==='全部'||h.track===radar.track)&&(radar.days==='all'||new Date(h.publishedAt)>=Date.now()-Number(radar.days)*86400000)&&(!radar.keyword||`${h.title} ${h.summary}`.toLowerCase().includes(radar.keyword.toLowerCase()))).sort((a,b)=>new Date(b.publishedAt)-new Date(a.publishedAt));const business=kind==='business';return heading(business?'BRAND & CULTURE':'A LITTLE INSPIRATION',savedOnly?'留住那些，值得拍的想法。':business?'让品牌，走进真实的生活。':'从正在发生的生活里，找灵感。','抖音 / 小红书 · 最近 1 天、3 天、7 天 · 按发布时间筛选',btn('录入热点链接','new-hotspot',kind,'primary','plus'))+`<div class="subnav">${business?'<a href="#business">商务项目</a><a class="active" href="#business-radar">商业热点雷达</a>':'<a href="#planning">选题库</a><a href="#radar" class="'+(!savedOnly?'active':'')+'">热点雷达</a><a href="#library" class="'+(savedOnly?'active':'')+'">灵感收藏</a>'}</div>${notice('数据状态：未连接平台授权接口。以下仅为<strong>示例内容或你手动录入的记录</strong>，不代表平台实时热榜。1 / 3 / 7 天按记录的发布时间筛选，不代表完整历史热度。','amber')}<form id="radar-form" class="filterbar"><label>平台<select name="platform">${['全部','抖音','小红书'].map(x=>`<option ${radar.platform===x?'selected':''}>${x}</option>`).join('')}</select></label><label>时间范围<select name="days">${savedOnly?'<option value="all">全部收藏时间</option>':''}${[1,3,7].map(x=>`<option value="${x}" ${Number(radar.days)===x?'selected':''}>最近 ${x} 天</option>`).join('')}</select></label><label>内容赛道<select name="track">${['全部','亲子','生活 Vlog','绘画'].map(x=>`<option ${radar.track===x?'selected':''}>${x}</option>`).join('')}</select></label><label>关键词<input name="keyword" placeholder="寻找一个灵感…" value="${esc(radar.keyword)}"></label><button class="btn primary" type="submit">${icon('search',15)}筛选记录</button></form><div class="section-head"><h2>${savedOnly?'已收藏灵感':business?'商业内容灵感':'灵感发现'} <small>${hs.length} 条</small></h2><small>按发布时间排序 · 不估算热度</small></div><div class="grid3">${hs.map(h=>`<article class="panel hot-card"><div class="card-top">${pill(h.platform,h.platform==='小红书'?'red':'gray')}${pill(h.track)}${pill(h.source==='示例数据'?'示例':'手动录入','amber')}</div><h3>${esc(h.title)}</h3><p>${esc(h.summary)}</p><div class="source">发布：${date(h.publishedAt,true)}<br>记录：${date(h.collectedAt,true)}<br>${h.heat?`手动指标：${esc(h.heat)}（未经核验）`:'热度指标：未提供'}<br>${safeUrl(h.url)?`<a class="source-link" href="${esc(safeUrl(h.url))}" target="_blank" rel="noopener noreferrer">查看原始链接 ↗</a>`:'示例灵感，无对应原始视频链接'}</div><div class="card-actions">${btn(S.favorites.includes(h.id)?'已收藏':'收藏','favorite',h.id,'small','bookmark')}${btn(business?'匹配品牌并转选题':'转为选题','hot-to-topic',h.id,'small soft','arrow')}</div></article>`).join('')}</div>${!hs.length?empty('这个范围里，还没有记录','试试扩大时间范围，或粘贴你发现的热点链接。'):''}${S.searches.length?`<div class="panel" style="margin-top:24px"><div class="section-head"><h2>最近筛选</h2></div><div class="actions">${S.searches.slice(-5).reverse().map((s,i)=>btn(`${s.platform} · ${s.days}天 · ${esc(s.keyword||s.track)}`,'history-search',String(S.searches.length-1-i),'small')).join('')}</div></div>`:''}`;}
function projectLists(mode){const ps=scoped();if(mode==='production'){const groups=[['待开拍',p=>p.stage<=2],['拍摄中',p=>p.stage===3],['剪辑与审核',p=>p.stage===4],['待发布 / 已发布',p=>p.stage>=5]];return heading('MAKE IT HAPPEN','让内容，一步一步向前。','只关注制作进度、剪辑结果与最终确认。',btn('新建视频','new-project','','primary','plus'))+`<div class="board">${groups.map(([t,fn])=>`<section class="board-col"><h3>${t}<span>${ps.filter(fn).length}</span></h3>${ps.filter(fn).map(p=>`<a style="display:block" class="board-card" href="#project/${p.id}">${pill(creator(p.creatorId).name,'gray')}<h4>${esc(p.title)}</h4>${pill(C.STAGES[p.stage],stageClass(p.stage))}<div class="row-meta">${p.stage===4?esc(p.editStatus):p.stage===3?esc(p.shootStatus):p.metrics?compact(p.metrics.plays)+' 播放':'计划 '+date(p.due)}</div></a>`).join('')}</section>`).join('')}</div>`;}
if(mode==='business'){const bp=ps.filter(p=>p.brand);return heading('BETTER BRAND STORIES','把品牌需求，翻译成好内容。','Brief、达人待确认事项与商单进度，放在同一条视频里。',btn('新建商单','new-project','business','primary','plus'))+`<div class="subnav"><a class="active" href="#business">商务项目</a><a href="#business-radar">${icon('flame',14)} 商业热点雷达</a></div>${notice('“达人沟通”用于整理拍摄时间、内容边界、产品到货与必带信息等待确认事项。由你沟通后手动勾选，不会自动发送消息。')}<div class="grid2">${bp.map(p=>`<section class="panel"><div class="section-head"><h2>${esc(p.brand)}</h2>${pill(C.STAGES[p.stage],stageClass(p.stage))}</div><h3 style="font-size:15px;margin-bottom:16px">${esc(p.title)}</h3><p class="copy">${esc(p.brief||'Brief 待补充')}</p><div class="form-footer"><span class="copy">${esc(creator(p.creatorId).name)} · ${(p.needs||[]).filter(n=>!n.done).length} 项待确认</span>${linkBtn('打开项目','project/'+p.id,'small','arrow')}</div></section>`).join('')}</div>${!bp.length?empty('还没有商单项目','新建商单，或把商业热点匹配到品牌需求。'):''}`;}
const isReview=mode==='reviews', rows=ps.filter(p=>isReview?p.stage>=6:p.stage>=1);return heading(isReview?'LEARN FROM EVERY STORY':'WORDS INTO SCENES',isReview?'每一次复盘，都为下一条而写。':'让想法，有画面也有声音。',isReview?'数据是依据，建议是参考，方向由编导亲自确认。':'模拟生成可编辑脚本与拍摄清单，保留达人的真实表达。')+notice(isReview?'对比仅使用同达人、同平台、同统计窗口的既往视频。示例数据不能证明内容效果；分析不将相关性当成因果。':'脚本生成采用本地规则模拟，没有调用真实模型。生成后请根据拍摄实际修改。')+`<section class="panel">${rows.length?rows.map(videoRow).join(''):empty(isReview?'发布后再来看看':'还没有已确认的选题',isReview?'完成发布与数据录入，即可生成单条复盘。':'先确认选题，再进入脚本创作。')}</section>`;}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function area(label,name,value='',extra=''){return `<label>${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;}
function options(values,selected){return values.map(x=>`<option value="${esc(Array.isArray(x)?x[0]:x)}" ${String(Array.isArray(x)?x[0]:x)===String(selected)?'selected':''}>${esc(Array.isArray(x)?x[1]:x)}</option>`).join('');}
const select=(label,name,values,selected)=>`<label>${label}<select name="${name}">${options(values,selected)}</select></label>`;
function workflowForm(p){
const c=creator(p.creatorId), ft=(save,next,action)=>`<div class="form-footer"><button class="btn" type="submit">${save}</button>${next?btn(next,action,p.id,'primary','arrow'):''}</div>`;
if(p.stage===0)return `<div class="section-title"><span>01</span><h2>把选题，先想清楚。</h2></div>${notice('请先保存你的修改，再由编导确认选题。确认后才能生成脚本。')}<form id="topic-form" data-id="${p.id}" class="form-section">${field('选题标题','title',p.title,'text','required maxlength="100"')}${area('切入角度 / 这条视频想表达什么','angle',p.angle,'required')}${field('计划发布日期','due',p.due,'date','required')}<div class="copy">灵感来源：${esc(p.source)} ${p.parentId?`<a class="source-link" href="#project/${p.parentId}">查看上一条复盘 ↗</a>`:''}</div>${ft('保存选题','我确认选题，进入脚本','confirm-topic')}</form>`;
if(p.stage===1)return `<div class="section-title"><span>02</span><h2>把文字，变成可拍的画面。</h2></div>${notice('本地规则模拟 · 未调用真实 AI。草稿会结合选题和达人档案，你可以自由修改。')}<div class="actions" style="margin-bottom:20px">${btn(p.script?'重新生成模拟草稿':'生成脚本与拍摄方案','generate-script',p.id,'soft','spark')}</div><form id="script-form" data-id="${p.id}" class="form-section">${area('视频脚本 / 口播草稿','script',p.script,'class="script-area" required placeholder="先生成一个草稿，或直接在这里写下你的脚本。"')}${area('拍摄方案 / 场景、设备、镜头清单','shootPlan',p.shootPlan,'required')}${ft('保存脚本与方案','确认脚本，进入沟通','confirm-script')}</form>`;
if(p.stage===2)return `<div class="section-title"><span>03</span><h2>开拍之前，把期待对齐。</h2></div>${notice('可选商单分支：没有品牌也可以继续。沟通事项由你确认后勾选；这里不会发送消息。')}<form id="communication-form" data-id="${p.id}" class="form-section">${field('品牌名称（选填）','brand',p.brand,'text','maxlength="80"')}${area('品牌 Brief / 必带信息 / 内容边界（选填）','brief',p.brief,'placeholder="品牌目标、产品卖点、必带画面、交付要求、不能提及的信息…"')}<button class="btn" type="submit">保存品牌 Brief</button></form><div style="margin-top:26px"><div class="section-head"><h2>达人 / 品牌待确认事项</h2><small>${p.needs.filter(n=>n.done).length} / ${p.needs.length} 已确认</small></div><div class="form-section">${p.needs.map((n,i)=>`<label class="checkrow ${n.done?'done':''}"><input type="checkbox" data-action="toggle-need" data-id="${p.id}" data-index="${i}" ${n.done?'checked':''}><span>${esc(n.text)}</span></label>`).join('')||'<p class="copy">暂无待确认事项。你可以添加拍摄时间、产品到货、人物意愿等问题。</p>'}</div><form id="need-form" data-id="${p.id}" class="inline-fields" style="margin-top:18px"><input name="text" aria-label="待确认事项" required maxlength="160" placeholder="添加一件需要对齐的小事…"><button class="btn" type="submit">添加</button></form></div><div class="form-footer"><span class="copy">全部确认后，才能进入拍摄。</span>${btn('沟通已确认，进入拍摄','confirm-communication',p.id,'primary','arrow')}</div>`;
if(p.stage===3)return `<div class="section-title"><span>04</span><h2>让真实的故事，发生在镜头前。</h2></div><div class="readbox">${esc(p.shootPlan)}</div><form id="shoot-form" data-id="${p.id}" class="form-section" style="margin-top:22px">${select('当前拍摄状态','shootStatus',['未开始','拍摄中','已完成'],p.shootStatus)}${area('素材与拍摄记录（选填）','shootNotes',p.shootNotes||'','placeholder="素材已备份的位置、实际拍摄情况、缺失镜头…"')}${ft('保存拍摄进度','确认素材齐备，交给剪辑','finish-shoot')}</form>`;
if(p.stage===4)return `<div class="section-title"><span>05</span><h2>少一点来回，多一点确认。</h2></div>${notice('只记录剪辑进度和修改结果。提交后由编导通过或退回，不需要复杂的时间码批注。')}<form id="edit-form" data-id="${p.id}" class="form-section"><div class="form-grid">${field('剪辑负责人（选填）','editor',p.editor||'')}${select('剪辑进度','editStatus',['未开始','剪辑中','修改中','待审核'],p.editStatus==='已通过'?'待审核':p.editStatus)}</div>${field('成片 / 审片链接（选填）','videoUrl',p.videoUrl||'','url','placeholder="https://…"')}${area('本次提交的修改结果','editResult',p.editResult,'required placeholder="例如：V2 已缩短开场，完成字幕校对与品牌信息核对。"')}<div class="form-footer"><button class="btn" type="submit">保存剪辑进度</button>${btn('提交结果，等待审核','submit-edit',p.id,'soft')}</div></form><div class="confirm-box"><h3>编导审核 · V${p.version||1}</h3><p class="copy">当前状态：${esc(p.editStatus)}。请打开成片核对内容，再确认结果。</p>${safeUrl(p.videoUrl)?`<a class="source-link copy" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(p.videoUrl))}">打开成片链接 ↗</a>`:''}<div class="actions" style="margin-top:20px">${btn('退回继续修改','return-edit',p.id,'')}${btn('我确认修改结果，准予发布','approve-edit',p.id,'primary','check')}</div></div>`;
if(p.stage===5){const m=p.metrics||{};return `<div class="section-title"><span>06</span><h2>发布之后，给数据一点时间。</h2></div>${notice('此处登记发布信息，不会自动发布到平台。请选择统一统计窗口，并录入该窗口结束时的数据。')}<form id="publish-form" data-id="${p.id}" class="form-section"><div class="form-grid">${select('发布平台','platform',['抖音','小红书'],p.platform||'抖音')}${field('发布时间','publishedAt',localInput(p.publishedAt),'datetime-local','required')}${field('视频原始链接（选填）','publishUrl',p.publishUrl||'','url','placeholder="https://…"')}${select('统计窗口（发布后）','window',[[24,'24 小时'],[72,'3 天'],[168,'7 天']],m.window||24)}</div>${evidencePanel(p)}<div class="section-head" style="margin:5px 0 0"><h2>录入单条视频数据</h2>${btn('填入演示数据','demo-metrics',p.id,'small soft','spark')}</div><div class="form-grid">${[['播放量','plays'],['完播率 (%)','completion'],['点赞数','likes'],['评论数','comments'],['收藏数','saves'],['分享数','shares'],['新增关注','follows']].map(([l,k])=>field(l,k,m[k]??'','number',`required min="0" ${k==='completion'?'max="100" step="0.01"':'step="1"'}`)).join('')}${field('数据来源','source',m.source||'','text','required placeholder="例如：抖音创作者中心，人工录入"')}${field('采集时间','collectedAt',localInput(m.collectedAt),'datetime-local','required')}</div>${m.source==='示例数据'?notice('当前为示例数据，请勿作为真实经营表现。','amber'):''}<div class="form-footer">${btn('先登记发布，开始视频分析','register-publication',p.id,'soft','video')}<button class="btn primary" type="submit">保存发布与数据，进入复盘 ${icon('arrow',15)}</button></div></form>`;}
if(p.stage===6)return reviewPanel(p);
return evidenceSummary(p)+`<div class="section-title"><span>08</span><h2>下一条，从这一次的收获开始。</h2></div>${notice('最终方向已经由编导确认。只有点击创建，才会生成下一条待确认选题。')}<div class="confirm-box"><h3>编导确认的方向</h3><p class="copy" style="white-space:pre-wrap">${esc(p.direction.text)}</p><p class="copy" style="margin-top:14px">${esc(p.direction.by)} · ${date(p.direction.at,true)} 亲自确认</p></div><div class="new-draft"><h3>把已确认的方向，带到下一次创作</h3><p class="copy">保留本条复盘关联，新选题仍需要编导确认。</p><div class="actions" style="margin-top:20px">${p.nextId?linkBtn('打开下一条策划','project/'+p.nextId,'primary','arrow'):btn('按确认方向创建下一条策划','create-next',p.id,'primary','plus')}${linkBtn('去周会汇报','weekly','','calendar')}</div></div>${p.review?`<details style="margin-top:24px"><summary class="copy">查看本条数据与复盘依据</summary><p class="evidence">${esc(p.review.summary)}</p><p class="copy">${esc(p.review.mode)} · ${p.review.sampleIds.length} 条历史样本</p></details>`:''}`;
}
function reviewPanel(p){const r=p.review,m=p.metrics;let content=evidenceSummary(p)+`<div class="section-title"><span>07</span><h2>先看数据，再决定方向。</h2></div>${notice('本地规则模拟 · 参考建议不会自动执行。逐条处理建议，并亲自确认最终方向。')}`;
if(r?.contentAnalysis)content+=notice('本次参考建议已结合视频内容观察。来源：'+esc(r.contentAnalysis.evidenceSource)+' · '+date(r.contentAnalysis.generatedAt,true)+'。请逐条判断，再亲自确认方向。');
if(!r)return content+`<div class="metric-grid"><div class="metric-box"><small>播放量</small><b>${compact(m.plays)}</b></div><div class="metric-box"><small>完播率</small><b>${m.completion}%</b></div><div class="metric-box"><small>数据窗口</small><b>${m.window}h</b></div></div><p class="evidence">来源：${esc(m.source)} · 采集：${date(m.collectedAt,true)}<br>会寻找同达人、同平台、同统计窗口的既往样本进行对比。</p><div class="form-footer">${btn('修改录入数据','edit-metrics',p.id)}${btn('生成数据复盘与参考建议','generate-review',p.id,'primary','spark')}</div>`;
const comps=r.sampleIds.map(id=>S.projects.find(p=>p.id===id)).filter(Boolean),max=Math.max(m.plays,...comps.map(p=>p.metrics.plays));
content+=`<div class="section-head"><h2>数据事实</h2>${btn('修改录入数据','edit-metrics',p.id,'small')}${pill(m.source==='示例数据'?'示例数据':m.source,'amber')}</div><div class="metric-grid"><div class="metric-box"><small>播放量</small><b>${compact(m.plays)}</b><em>统计窗口 ${m.window}h</em></div><div class="metric-box"><small>完播率</small><b>${m.completion}%</b><em>${r.base?'历史中位数 '+r.base.completion+'%':'暂无同口径基线'}</em></div><div class="metric-box"><small>互动总次数 / 播放量</small><b>${r.interactionRate.toFixed(2)}%</b><em>含赞评藏转，非去重人数</em></div></div><div class="chart">${[...comps.slice(-3),p].map((x,i)=>`<div class="chart-col" style="height:${Math.max(3,x.metrics.plays/max*85)}%"><span>${compact(x.metrics.plays)}</span><small>${x.id===p.id?'本条视频':'历史 '+(i+1)}</small></div>`).join('')}</div><p class="evidence">${esc(r.summary)}</p><details style="margin:12px 0 22px"><summary class="copy">查看数据口径与历史样本 (${comps.length})</summary><p class="copy">来源：${esc(m.source)}；采集：${date(m.collectedAt,true)}；${esc(p.platform)} 发布后 ${m.window} 小时。互动率 =（赞 + 评 + 藏 + 转）÷ 播放量。播放量不等于独立用户、收入或转化。</p>${comps.map(x=>`<a class="source-link copy" href="#project/${x.id}">${esc(x.title)} · ${compact(x.metrics.plays)} 播放</a><br>`).join('')||'<p class="copy">暂无可比样本，不进行优劣排名。</p>'}</details><div class="section-head"><h2>参考建议 <small> / 假设，待验证</small></h2>${pill('模拟生成','gray')}</div>`;
content+=r.suggestions.map((s,i)=>{const d=p.decisions[i];return `<section class="suggestion"><h3>0${i+1} · ${esc(s.title)}</h3><p class="copy">${esc(s.text)}</p><div class="basis">依据：${esc(s.basis)}</div><div class="decision">${[['adopt','采纳'],['modify','修改'],['reject','拒绝']].map(([k,t])=>`<button class="${d.choice===k?'selected':''}" data-action="decision" data-id="${p.id}" data-index="${i}" data-choice="${k}">${d.choice===k?icon('check',12):''} ${t}</button>`).join('')}</div>${d.choice==='modify'?`<label style="margin-top:12px">你的调整<textarea data-review-edit="${i}" data-id="${p.id}" aria-label="修改建议 ${i+1}">${esc(d.text)}</textarea></label>`:''}</section>`;}).join('');
return content+`<form id="direction-form" data-id="${p.id}" class="confirm-box"><h3>最终方向，由你决定。</h3><p class="copy">${p.decisions.filter(d=>d.choice).length} / ${r.suggestions.length} 条建议已处理。可以综合采纳内容，也可以全部拒绝后写下你的判断。</p>${btn('整理已采纳 / 修改的建议','compose-direction',p.id,'small')}${area('下一条视频的最终调整方向','text',p.directionDraft||'','required placeholder="写下你真正决定执行的方向、验证指标与拍摄边界…"')}${field('确认人','by',S.preferences.reviewer,'text','required maxlength="40"')}<label class="checkrow"><input name="confirmed" type="checkbox" required><span>我已查看数据和参考建议，亲自确认此方向。</span></label><button type="submit" class="btn primary" style="margin-top:14px">确认最终方向 ${icon('check',15)}</button></form>`;
}
function projectPage(id){const p=S.projects.find(p=>p.id===id);if(!p)return empty('没有找到这个项目','它可能不在当前浏览器的记录里。',linkBtn('回到工作总览','home'));const c=creator(p.creatorId);return heading('A STORY IN THE MAKING',esc(p.title),`${esc(c.name)} · ${esc(c.track)} ${p.demo?'· 完整流程演示项目':''}`,linkBtn('返回工作总览','home','header-back','back'))+`<div class="steps">${C.STAGES.map((s,i)=>`<div class="step ${i===p.stage?'active':i<p.stage?'complete':''}"><div class="num">${i<p.stage?icon('check',12):i+1}</div>${s}</div>`).join('')}</div>${analysisAvailable(p)?analysisCallout(p):''}<div class="project-grid"><section class="panel">${workflowForm(p)}</section><aside class="project-aside"><section class="panel"><div class="creator-top">${avatar(c)}<div><h3 style="margin:0 0 6px">${esc(c.name)}</h3>${pill(c.track)}</div></div><p>${esc(c.profile)}</p><div class="facts"><span>负责人</span><b>${esc(c.owner)}</b></div><div class="facts"><span>计划发布</span><b>${date(p.due)}</b></div><div class="facts"><span>合作状态</span><b>${esc(c.status)}</b></div><p>内容边界：${esc(c.taboos||'待补充')}</p></section><section class="panel"><h3>这条内容的初衷</h3><p>${esc(p.angle)}</p>${p.parentId?`<a class="source-link copy" href="#project/${p.parentId}">来自上一条已确认的复盘 ↗</a>`:''}${p.script&&p.stage!==1?`<details style="margin-top:16px"><summary class="copy">查看脚本与拍摄方案</summary><div class="readbox" style="margin-top:12px">${esc(p.script)}\n\n${esc(p.shootPlan)}</div></details>`:''}</section><section class="panel"><h3>流程记录</h3><div class="timeline"><div>创建视频项目<br>${date(p.createdAt,true)}</div>${p.history.map(h=>`<div>${esc(({confirmTopic:'编导确认选题',confirmScript:'脚本与方案确认',confirmCommunication:'沟通事项确认',finishShoot:'拍摄与素材确认',approveEdit:'剪辑结果审核通过',registerPublication:'登记发布，开始视频分析',publish:'登记发布与数据',confirmDirection:'编导确认最终方向',returnEdit:'退回剪辑修改',submitEdit:'提交剪辑结果',dataRevision:'修正数据，重新复盘'})[h.action]||h.action)}<br>${date(h.at,true)} · ${esc(h.by||'我')}</div>`).join('')}</div></section></aside></div>`;}
function weeklyData(){const ps=scoped(),since=Date.now()-7*86400000;return {published:ps.filter(p=>p.stage>=6&&new Date(p.publishedAt)>=since),active:ps.filter(p=>p.stage<6),confirmed:ps.filter(p=>p.direction&&new Date(p.direction.at)>=since),pending:ps.filter(p=>p.stage===6)};}
function weeklyPage(){const w=weeklyData();return heading('A WEEK WORTH SHARING','把这一周，讲清楚。','近 7 天动态汇总 · 引用编导已经确认的方向。',btn('导出周会提纲','export-weekly','','primary','download'))+`<section class="panel"><div class="report-head"><div class="eyebrow">JIMU / WEEKLY REVIEW</div><h2>内容周会 · ${date(new Date(Date.now()-6*86400000))} — ${date(new Date())}</h2><p>${filterCreator==='all'?'全部负责中的达人':esc(creator(filterCreator).name)} · ${activeCreators().length} 位在负责达人 · 含示例数据</p></div><div class="stats" style="margin-top:25px">${stat('近 7 天发布',w.published.length,'按发布时间登记','video')}${stat('制作中',w.active.length,'继续推进项目','clock')}${stat('已确认方向',w.confirmed.length,'按确认时间统计','check')}${stat('待编导复盘',w.pending.length,'不列入最终执行方向','chart')}</div><section class="weekly-section"><h3>01 / 这一周，内容表现如何</h3>${w.published.map(p=>`<div class="weekly-row"><b><a href="#project/${p.id}">${esc(creator(p.creatorId).name)} · ${esc(p.title)} ↗</a></b>${fmt(p.metrics.plays)} 播放 · ${p.metrics.completion}% 完播 · ${esc(p.platform)} / ${p.metrics.window}h · ${esc(p.metrics.source)}<br><span class="copy">${p.review?esc(p.review.summary):'尚未生成单条复盘，暂不推断表现原因。'}</span></div>`).join('')||'<p class="copy">此范围内暂无发布记录。</p>'}</section><section class="weekly-section"><h3>02 / 编导已确认的下一步方向</h3>${w.confirmed.map(p=>`<div class="weekly-row"><b>${esc(creator(p.creatorId).name)} · ${esc(p.title)}</b><div style="white-space:pre-wrap">${esc(p.direction.text)}</div><span class="copy">${esc(p.direction.by)} · ${date(p.direction.at,true)} 确认 · </span><a class="source-link" href="#project/${p.id}">查看来源复盘 ↗</a>${p.nextId?`<br><a class="source-link" href="#project/${p.nextId}">已关联下一条策划 ↗</a>`:''}</div>`).join('')||'<p class="copy">暂无已确认方向。未确认的模拟建议不会进入此处。</p>'}</section><section class="weekly-section"><h3>03 / 下周继续推进</h3>${w.active.map(p=>`<div class="weekly-row"><b><a href="#project/${p.id}">${esc(p.title)} ↗</a></b>${esc(creator(p.creatorId).name)} · 下一步：${C.STAGES[p.stage]} · 计划 ${date(p.due)}</div>`).join('')||'<p class="copy">没有进行中的项目。</p>'}</section></section>`;}
function settings(){return heading('MAKE IT YOURS','让工作台，适合你的习惯。','当前是浏览器本地原型，适合演示与个人试用。')+`<div class="grid2"><section class="panel"><div class="section-head"><h2>数据与备份</h2>${pill('LocalStorage')}</div><p class="copy">数据仅保存在当前浏览器、当前网址。同一网址刷新后会保留；不同设备、不同浏览器与本地 / 在线地址之间不会同步。后台截图也保存在本机，导出备份会包含截图原图。清除浏览器数据会丢失记录，请定期导出。</p><div class="actions" style="margin-top:20px">${btn('导出完整备份','export-data','','','download')}${btn('导入备份','import-data','','','file')}</div><input type="file" id="backup-input" accept="application/json,.json" hidden><div class="form-footer">${btn('恢复初始演示数据','reset-data','','danger')}</div></section><section class="panel"><div class="section-head"><h2>生成服务</h2>${pill('模拟模式','amber')}</div><p class="copy">脚本与复盘使用本地规则模拟，未连接真实 AI。不会向第三方发送达人档案、脚本或经营数据。后续可通过独立服务接口接入模型，并由服务端保管密钥。</p><form id="preferences-form" style="margin-top:20px" class="form-section">${field('默认确认人','reviewer',S.preferences.reviewer,'text','required maxlength="40"')}<button type="submit" class="btn">保存偏好</button></form></section><section class="panel"><div class="section-head"><h2>热点数据</h2>${pill('示例 / 手动录入','amber')}</div><p class="copy">未连接抖音、小红书授权数据源。支持手动录入原始链接、平台、发布时间与指标。后台数据可上传截图并在本地识别核对。示例热点不冒充真实热榜；不根据发布时间推断热度增长。</p><div class="actions" style="margin-top:20px">${linkBtn('选题热点雷达','radar','small')}${linkBtn('商业热点雷达','business-radar','small')}</div></section><section class="panel"><div class="section-head"><h2>体验完整流程</h2>${icon('play')}</div><p class="copy">选题确认 → 脚本 → 沟通 → 拍摄 → 剪辑审核 → 发布数据 → 单条复盘 → 亲自确认方向 → 下一条策划。</p><div style="margin-top:20px">${btn('从当前演示进度继续','demo','','primary','play')}</div></section></div>`;}
function render(){const [page,id]=getRoute();const body=page==='home'?home():page==='creators'?creatorsPage():page==='planning'?planning():['radar','business-radar','library'].includes(page)?radarPage(page==='business-radar'?'business':'topic',page==='library'):['production','business','scripts','reviews'].includes(page)?projectLists(page):page==='analysis'?analysisPage(id):page==='project'?projectPage(id):page==='weekly'?weeklyPage():page==='settings'?settings():home();$('#app').innerHTML=shell(body,page);document.title=(pageNames[page]||'工作总览')+' · 积木工作台';if(page==='analysis'&&id)mountAnalysisPlayer(id);hydrateEvidence();}
function modal(title,body){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="section-head"><h2 id="modal-title">${title}</h2><button class="close" data-action="close-modal" aria-label="关闭弹窗">${icon('close',16)}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input:not([type=hidden]),.modal textarea,.modal button')?.focus(),30);}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';modalReturn?.focus();}
function confirmModal(title,copy,action,id='',label='确认'){modal(title,`<p class="copy">${copy}</p><div class="form-footer">${btn('取消','close-modal')}${btn(label,action,id,'primary')}</div>`);}
function creatorModal(c){modal(c?'编辑达人档案':'认识一位新的创作者',`<form id="creator-form" data-id="${c?.id||''}" class="form-section"><div class="form-grid">${field('达人名称','name',c?.name||'','text','required maxlength="40"')}${select('内容赛道','track',['亲子','生活 Vlog','绘画'],c?.track||'亲子')}${field('负责人','owner',c?.owner||'我','text','required maxlength="40"')}${select('合作状态','status',['负责中','暂停','已移交','已归档'],c?.status||'负责中')}</div>${field('一句话定位','tag',c?.tag||'','text','maxlength="100"')}${area('人物特点 / 观众偏好 / 表达风格','profile',c?.profile||'','required')}${area('内容边界 / 不接受的表达','taboos',c?.taboos||'')}<button class="btn primary" type="submit">${c?'保存档案':'创建达人空间'}</button></form>`);}
function newProjectModal(h,business=false){const selected=filterCreator!=='all'&&creator(filterCreator)?.status==='负责中'?filterCreator:activeCreators()[0]?.id;if(!selected){toast('请先新增或恢复一位负责中的达人。',true);go('creators');return;}modal(h?'把灵感，变成一个新选题':business?'创建一个新的商单项目':'开始一条新的内容',`<form id="new-project-form" data-hotspot="${h?.id||''}" class="form-section"><label>选择达人<select name="creatorId">${creatorOptions(selected,true)}</select></label>${field('选题标题','title',h?.title||'','text','required maxlength="100"')}${area('内容切入角度','angle',h?.summary||'','required')}${field('计划发布日期','due',new Date(Date.now()+2*86400000).toISOString().slice(0,10),'date','required')}${h?.kind==='business'||business?`${field('对应品牌','brand','','text','required maxlength="80"')}${area('品牌需求 / 为什么适合这个热点','brief','','required placeholder="明确产品、场景与品牌必带信息的对应关系。"')}`:''}<button class="btn primary" type="submit">创建待确认选题 ${icon('arrow',14)}</button></form>`);}
function hotspotModal(kind){modal(kind==='business'?'录入一条商业热点':'记录你发现的灵感',`<form id="hotspot-form" data-kind="${kind}" class="form-section">${notice('仅保存你提供的信息，不会自动抓取链接内容或补造平台数据。','amber')}${field('内容标题','title','','text','required maxlength="100"')}${field('原始内容链接','url','','url','required placeholder="https://…"')}<div class="form-grid">${select('来源平台','platform',['抖音','小红书'],'抖音')}${select('内容赛道','track',['亲子','生活 Vlog','绘画'],'亲子')}${field('原内容发布时间','publishedAt',localInput(),'datetime-local','required')}${field('指标与口径（选填）','heat','','text','placeholder="例如：2.3万点赞，采集时可见"')}</div>${area('内容概述 / 可参考的角度','summary','','required')}<button class="btn primary" type="submit">保存手动记录</button></form>`);}
const currentProject=id=>{const p=S.projects.find(p=>p.id===id);if(!p)throw Error('项目不存在。');return p;};
function formValues(form){return Object.fromEntries(new FormData(form));}
function validForm(form){if(!form?.reportValidity())throw Error('请检查并填写必填信息。');return formValues(form);}
function updateForm(form,silent=false){const d=validForm(form),p=currentProject(form.dataset.id);if(form.id==='topic-form')Object.assign(p,{title:d.title.trim(),angle:d.angle.trim(),due:d.due});
if(form.id==='script-form')Object.assign(p,{script:d.script.trim(),shootPlan:d.shootPlan.trim()});
if(form.id==='communication-form')Object.assign(p,{brand:d.brand.trim(),brief:d.brief.trim()});
if(form.id==='shoot-form')Object.assign(p,{shootStatus:d.shootStatus,shootNotes:d.shootNotes});
if(form.id==='edit-form')Object.assign(p,{editor:d.editor,editStatus:d.editStatus,videoUrl:d.videoUrl,editResult:d.editResult.trim()});
p.updatedAt=C.iso();persist(silent?'':'已保存');return p;}
function stepAction(id,action,formId){const p=currentProject(id);if(formId&&$('#'+formId))updateForm($('#'+formId),true);C.transition(p,action,{by:S.preferences.reviewer});persist('已确认，进入下一步');render();window.scrollTo({top:0,behavior:'smooth'});}
function download(name,data,type='application/json'){const blob=new Blob([data],{type}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function weeklyText(){const w=weeklyData();return `积木工作台 · 近 7 天内容周会\n生成时间：${new Date().toLocaleString('zh-CN')}\n范围：${filterCreator==='all'?'全部负责中的达人':creator(filterCreator).name}\n说明：包含示例数据；模拟建议未经确认不会进入最终方向。\n\n一、发布与表现\n${w.published.map(p=>`${creator(p.creatorId).name}｜${p.title}\n${fmt(p.metrics.plays)} 播放 / ${p.metrics.completion}% 完播 / ${p.platform} / ${p.metrics.window}h / ${p.metrics.source}\n${p.review?.summary||'尚未复盘，不推断原因。'}`).join('\n\n')||'暂无发布'}\n\n二、编导确认的方向\n${w.confirmed.map(p=>`${p.title}\n${p.direction.text}\n确认人：${p.direction.by}；确认时间：${p.direction.at}；项目编号：${p.id}${p.nextId?'；下一条：'+p.nextId:''}`).join('\n\n')||'暂无确认方向'}\n\n三、继续推进\n${w.active.map(p=>`${p.title}｜${creator(p.creatorId).name}｜下一步：${C.STAGES[p.stage]}｜计划日期：${p.due}`).join('\n')||'暂无进行中项目'}`;}
let pendingBackup;
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id,index,choice}=el.dataset;
try{
if(action==='menu'){$('.sidebar').classList.toggle('open');$('.mobile-shade').classList.toggle('visible');return;}
if(action==='close-modal'){closeModal();return;}
if(action==='demo'){let p=S.projects.find(p=>p.demo);if(!p){const c=activeCreators()[0];if(!c){toast('先添加一位达人，再体验流程。',true);go('creators');return;}p=C.project(c.id,'让孩子决定，周末的 100 元怎么花',{demo:true});S.projects.unshift(p);persist();}go('project/'+p.id);return;}
if(action==='dash-tab'){dashTab=id;render();return;}
if(action==='creator-tab'){creatorTab=id;render();return;}
if(action==='select-creator'){filterCreator=id;go('production');render();return;}
if(action==='new-creator'){creatorModal();return;}
if(action==='edit-creator'){creatorModal(creator(id));return;}
if(action==='transfer-creator'){const c=creator(id);modal('移交达人与历史记录',`<form id="transfer-form" data-id="${id}" class="form-section"><p class="copy">${esc(c.name)} 的 ${S.projects.filter(p=>p.creatorId===id).length} 条视频、策划与复盘都会保留，并关联新的负责人。此处只记录移交，不会邀请或通知对方。</p>${field('新负责人','owner','','text','required maxlength="40"')}${area('交接说明','note','','required placeholder="下一步要跟进什么？哪些事项还没有确认？"')}<button type="submit" class="btn primary">确认移交</button></form>`);return;}
if(action==='archive-creator'){const c=creator(id);confirmModal(c.status==='已归档'?'恢复负责这位达人':'归档这位达人',c.status==='已归档'?'恢复后，该达人重新出现在日常工作列表中。':'归档后从日常工作列表隐藏；所有视频、脚本、数据与复盘会保留，可随时恢复。','confirm-archive',id,c.status==='已归档'?'恢复负责':'确认归档');return;}
if(action==='confirm-archive'){const c=creator(id);c.status=c.status==='已归档'?'负责中':'已归档';c.history.push({at:C.iso(),text:c.status==='已归档'?'归档，保留全部历史':'恢复负责'});if(filterCreator===id)filterCreator='all';persist('达人状态已更新，历史内容已保留');closeModal();render();return;}
if(action==='new-project'){newProjectModal(null,id==='business');return;}
if(action==='new-hotspot'){hotspotModal(id);return;}
if(action==='favorite'){S.favorites=S.favorites.includes(id)?S.favorites.filter(x=>x!==id):[...S.favorites,id];persist(S.favorites.includes(id)?'已加入灵感收藏':'已取消收藏');render();return;}
if(action==='hot-to-topic'){newProjectModal(S.hotspots.find(h=>h.id===id));return;}
if(action==='history-search'){Object.assign(radar,S.searches[Number(id)]);render();return;}
if(action==='confirm-topic'){stepAction(id,'confirmTopic','topic-form');return;}
if(action==='generate-script'){const p=currentProject(id);if(p.script||$('#script-form textarea')?.value.trim()){confirmModal('重新生成模拟草稿','新的草稿将替换当前脚本和拍摄方案。已确认的选题保持不变。','do-generate-script',id,'重新生成');return;}generateScript(id);return;}
if(action==='do-generate-script'){closeModal();generateScript(id);return;}
if(action==='confirm-script'){stepAction(id,'confirmScript','script-form');return;}
if(action==='toggle-need'){const p=currentProject(id);p.needs[Number(index)].done=el.checked;persist('确认事项已更新');return;}
if(action==='confirm-communication'){stepAction(id,'confirmCommunication','communication-form');return;}
if(action==='finish-shoot'){stepAction(id,'finishShoot','shoot-form');return;}
if(action==='submit-edit'){const p=updateForm($('#edit-form'),true);if(!p.editResult.trim())throw Error('请填写本次修改结果。');p.editStatus='待审核';p.history.push({action:'submitEdit',at:C.iso(),by:p.editor||'剪辑'});persist('结果已提交，等待编导审核');render();return;}
if(action==='return-edit'){const p=currentProject(id);if(p.editStatus!=='待审核')throw Error('请先提交剪辑结果，再进行审核。');p.editStatus='修改中';p.version=(p.version||1)+1;p.history.push({action:'returnEdit',at:C.iso(),by:S.preferences.reviewer});persist('已退回修改，保留上一版提交结果');render();return;}
if(action==='approve-edit'){stepAction(id,'approveEdit');return;}
if(action==='demo-metrics'){const p=currentProject(id);delete p.metricEntryDraft;p.platform='抖音';p.publishedAt=C.ago(26);p.metrics={plays:36000,completion:34,likes:1580,comments:142,saves:310,shares:186,follows:145,window:24,source:'示例数据',collectedAt:C.ago(2)};persist('已填入示例数据，请登记后再复盘');render();return;}
if(action==='generate-review'){const p=currentProject(id);p.review=C.review(p,S.projects);p.decisions=p.review.suggestions.map(s=>({choice:'',text:s.text}));persist('复盘已生成，参考建议等待你的判断');render();return;}
if(action==='edit-metrics'){confirmModal('修正本条视频数据','重新填写数据后，再生成复盘。当前尚未确认最终方向。','confirm-edit-metrics',id,'返回数据录入');return;}
if(action==='confirm-edit-metrics'){const p=currentProject(id);if(p.stage!==6)throw Error('已确认的方向不可直接改写数据。');p.stage=5;p.publicationRegistered=true;delete p.review;delete p.decisions;delete p.directionDraft;p.history.push({action:'dataRevision',by:S.preferences.reviewer,at:C.iso()});persist();closeModal();render();return;}
if(action==='decision'){const p=currentProject(id);p.decisions[Number(index)].choice=choice;persist();render();return;}
if(action==='compose-direction'){const p=currentProject(id);const text=p.decisions.filter(d=>['adopt','modify'].includes(d.choice)).map(d=>d.text).join('\n\n');if(!text)throw Error('先采纳或修改建议，或直接写下你自己的最终方向。');p.directionDraft=text;persist();render();return;}
if(action==='create-next'){const p=currentProject(id);const n=C.nextProject(p);S.projects.unshift(n);persist('已创建下一条待确认选题，并关联本次复盘');go('project/'+n.id);return;}
if(action==='export-data'){const backup=await packEvidenceBackup();download('积木工作台-数据备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(backup,null,2));toast('完整备份已导出');return;}
if(action==='import-data'){$('#backup-input').click();return;}
if(action==='confirm-import'){if(!pendingBackup)throw Error('没有有效备份。');S=await restoreEvidenceBackup(pendingBackup);pendingBackup=null;filterCreator='all';persist('备份已导入');closeModal();render();return;}
if(action==='reset-data'){confirmModal('恢复初始演示数据','这会替换当前浏览器中的所有修改。请先导出备份。此操作不影响已导出的文件。','confirm-reset','','确认恢复演示数据');return;}
if(action==='confirm-reset'){await evidenceStore('clear');for(const url of evidenceUrls.values())URL.revokeObjectURL(url);evidenceUrls.clear();S=C.seed();filterCreator='all';persist('已恢复初始演示数据');closeModal();go('home');render();return;}
if(action==='export-weekly'){download('积木工作台-周会提纲.txt',weeklyText(),'text/plain;charset=utf-8');toast('周会提纲已导出');return;}
}catch(err){toast(err.message,true);}
});
function generateScript(id){const p=currentProject(id);Object.assign(p,C.mockScript(p,creator(p.creatorId)));persist('已生成可编辑模拟草稿');render();}
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(['analysis-form','ocr-review-form'].includes(f.id))return;try{
if(['topic-form','script-form','communication-form','shoot-form','edit-form'].includes(f.id)){updateForm(f);return;}
const d=validForm(f);
if(f.id==='creator-form'){if(!d.name.trim()||!d.owner.trim()||!d.profile.trim())throw Error('名称、负责人和人物档案不能为空。');const existing=f.dataset.id,c=existing?creator(existing):{id:C.id(),color:['peach','sage','lilac','blue'][S.creators.length%4],history:[]};if(existing&&(c.owner!==d.owner||c.status!==d.status))c.history.push({at:C.iso(),text:`${c.owner} / ${c.status} → ${d.owner} / ${d.status}`});Object.assign(c,{...d,name:d.name.trim(),owner:d.owner.trim(),profile:d.profile.trim()});if(!c.name||!c.owner||!c.profile)throw Error('名称、负责人和人物档案不能为空。');if(!existing)S.creators.push(c);persist('达人档案已保存');closeModal();render();}
if(f.id==='transfer-form'){const c=creator(f.dataset.id);if(!d.owner.trim()||!d.note.trim())throw Error('请填写新负责人和交接说明。');c.history.push({at:C.iso(),text:`${c.owner} → ${d.owner.trim()}；${d.note.trim()}`});c.owner=d.owner.trim();c.status='已移交';if(filterCreator===c.id)filterCreator='all';persist('已记录移交，所有内容历史已保留');closeModal();render();}
if(f.id==='new-project-form'){if(!d.title.trim()||!d.angle.trim())throw Error('标题和切入角度不能为空。');const h=S.hotspots.find(h=>h.id===f.dataset.hotspot),p=C.project(d.creatorId,d.title.trim(),{angle:d.angle.trim(),due:d.due,brand:d.brand?.trim()||'',brief:d.brief?.trim()||'',source:h?h.source+' · '+h.title:'手动策划',hotspotId:h?.id||null});S.projects.unshift(p);persist('已创建选题，等待编导确认');closeModal();go('project/'+p.id);}
if(f.id==='hotspot-form'){if(!safeUrl(d.url))throw Error('请输入 http 或 https 原始链接。');if(new Date(d.publishedAt)>new Date())throw Error('原内容发布时间不能在未来。');if(!d.title.trim()||!d.summary.trim())throw Error('标题与内容概述不能为空。');S.hotspots.unshift({...d,id:C.id(),kind:f.dataset.kind,source:'手动录入',publishedAt:new Date(d.publishedAt).toISOString(),collectedAt:C.iso()});persist('已保存手动记录，未抓取或核验平台数据');closeModal();render();}
if(f.id==='radar-form'){Object.assign(radar,d);S.searches.push({...d,at:C.iso()});S.searches=S.searches.slice(-20);persist();render();}
if(f.id==='need-form'){const p=currentProject(f.dataset.id);if(!d.text.trim())throw Error('待确认事项不能为空。');p.needs.push({text:d.text.trim(),done:false});persist('已添加待确认事项');render();}
if(f.id==='publish-form'){const p=currentProject(f.dataset.id),m={};for(const k of ['plays','completion','likes','comments','saves','shares','follows','window'])m[k]=Number(d[k]);m.source=d.source.trim();m.collectedAt=new Date(d.collectedAt).toISOString();C.validateMetrics(m);const pub=new Date(d.publishedAt);if(pub>new Date())throw Error('登记的发布时间不能在未来。');if(new Date(m.collectedAt)>new Date())throw Error('数据采集时间不能在未来。');if(new Date(m.collectedAt).getTime()-pub.getTime()<m.window*3600000)throw Error('采集时间尚未满所选统计窗口，请调整发布时间、采集时间或窗口。');Object.assign(p,{platform:d.platform,publishedAt:pub.toISOString(),publishUrl:d.publishUrl,metrics:m});C.transition(p,'publish',{by:S.preferences.reviewer});delete p.metricEntryDraft;persist('发布与数据已登记，现在可以复盘');render();window.scrollTo(0,0);}
if(f.id==='direction-form'){const p=currentProject(f.dataset.id);C.transition(p,'confirmDirection',{text:d.text,by:d.by,checked:d.confirmed==='on'});persist('最终方向已由编导确认');render();window.scrollTo(0,0);}
if(f.id==='preferences-form'){if(!d.reviewer.trim())throw Error('确认人不能为空。');S.preferences.reviewer=d.reviewer.trim();persist('偏好已保存');}
}catch(err){toast(err.message,true);}});
document.addEventListener('change',async e=>{const t=e.target;
if(t.id==='creator-filter'){filterCreator=t.value;render();}
if(t.id==='backup-input'&&t.files[0]){try{if(t.files[0].size>48*1024*1024)throw Error('备份超过 48 MB，请使用更小的有效 JSON 备份。');pendingBackup=C.validateImport(JSON.parse(await t.files[0].text()));await validateEvidenceBackup(pendingBackup);confirmModal('导入这份备份',`包含 ${pendingBackup.creators.length} 位达人、${pendingBackup.projects.length} 条视频、${pendingBackup.screenshotFiles?.length||0} 张截图。将替换当前浏览器的数据，请先确保已导出当前备份。`,'confirm-import','','确认导入');}catch(e){toast(e.message||'备份读取失败',true);}t.value='';}
});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.reviewEdit!==undefined){const p=currentProject(t.dataset.id);p.decisions[Number(t.dataset.reviewEdit)].text=t.value;persist();}if(t.closest('#direction-form')&&t.name==='text'){const p=currentProject(t.closest('form').dataset.id);p.directionDraft=t.value;persist();}});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=[...$('.modal').querySelectorAll('button,input:not([type=hidden]),textarea,select,a[href]')].filter(el=>!el.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{S=C.validateImport(JSON.parse(e.newValue));render();toast('已同步另一个标签页保存的内容');}catch{toast('另一标签页的数据格式异常，请导出备份后检查。',true);}}});
render();
